(function(){"use strict";app.directive("btnDataAdicionalArticulo",function(t,i){return{restrict:"A",scope:{entity:"=",getDataEtiqueta:"&",datosAdicionales:"=",codDoc:"="},link:function(e,o){o.on("click",async function(){let o=parseFloat(e.entity.cantidad);if(!Number.isInteger(o))return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"El valor de la cantidad del artículo tiene que ser un número entero!"});let{fileCtrl:a,controller:n,template:l}=i.compra.MODAL_DATO_ADICIONAL_ARTICULO,c=(await import(a))[n],r=t.openModalCustom({controller:c,template:l,size:"lg",params:{entity:e.entity,datosAdicionales:e.datosAdicionales,codDoc:e.codDoc},isRenderRazorPartial:!0});r.result.then(function(t){if(angular.isArray(t)){if(e.datosAdicionales.some(t=>t.idArticulo===e.entity.idArticulo)){e.datosAdicionales=e.datosAdicionales.filter(t=>t.idArticulo!==e.entity.idArticulo);for(let i of t)e.datosAdicionales.push(i)}else for(let i of t)e.datosAdicionales.push(i);"01"===e.codDoc&&e.getDataEtiqueta({item:e.datosAdicionales})}})})}}})})(window.angular);